# Parágrafo final que o dono validou (27/11/2026): a IA "realmente refinou" (levou ~3 min contra ~1 min). Desligar com CRAFT=0.
CRAFT = ("\nWORK METHOD (important): take your time. Build the sheet calmly, one pose at a time, frame by frame, without rushing. When every pose is drawn, "
         "do a final REVIEW pass and fine-tune: compare each pose with the previous and the next one, fix any pose that breaks the identity, the hair, the hands, "
         "the katana or other held items, the scale, the ground line or the smoothness of the motion, and only then deliver the final image.\n")
def _craft(t): return t if os.environ.get("CRAFT") == "0" else t.rstrip("\n") + "\n" + CRAFT

def _colors(n, t):
    """Ninja com chave `colors` (ex.: Kazan) troca o limite padrão de 16 cores pelo dele (decidido 25/11/2026)."""
    c = n.get("colors")
    return t.replace("max 16 colors per character", c + " per character").replace("max 16 colors", c) if c else t
def row_prompts(k):
    """Lista de (anim, texto do prompt de UMA linha). Usa os mesmos textos dos lotes (n[lote]), uma linha por prompt."""
    import re
    n = NINJAS[k]; P = n["pal"]; N = n["name"]; out = []
    for lote, anims in ROWMAP:
        if lote not in n: continue
        rws = [l for l in n[lote].split("\n") if l.startswith("Row ")]
        for a, rw in zip(anims, rws):
            r1 = re.sub(r"^Row \d+:", "Row 1:", rw)
            if lote == "D":
                t = PIXEL + "\n" + DBLOCK.format(PAL=P, NAME=N).replace("EXACTLY 6 rows and EXACTLY 6 columns", "EXACTLY 1 row and EXACTLY 6 columns").replace("The image has 6 rows, not more.", "The image has 1 row, not more.").replace("LOTE D", a.upper()).replace("ROWS (each one effect, 6 frames):", "ROW (one effect, 6 frames):") + r1 + "\n"
            elif lote == "CL":
                t = RULES.format(N=1, PAL=P, NAME=N, L=a.upper()) + "\n" + ROWREF.format(NAME=N.title()) + PIXEL + LOCKS + "\n" + n["CLINTRO"] + f"Proportions: {PROP}.\n\nROWS:\n" + r1 + "\n"
            else:
                t = RULES.format(N=1, PAL=P, NAME=N, L=a.upper()) + "\n" + ROWREF.format(NAME=N.title()) + PIXEL + LOCKS + "\n" + TRUTH.format(NAME=N.title(), LOOK=n["look"]) + f"Proportions: {PROP}.\n\nROWS:\n" + r1 + "\n"
            out.append((a, _colors(n, t)))
    return out

def build(k):
    n = NINJAS[k]; P = n["pal"]; N = n["name"]
    def lot(rows, L, ref):
        return RULES.format(N=rows[0], PAL=P, NAME=N, L=L) + "\n" + (REF if ref else TRUTH.format(NAME=N.title(), LOOK=n["look"])) + PIXEL + LOCKS + "\nROWS:\n" + rows[1] + "\n"
    out = {}
    out["A1"] = RULES.format(N=n["A1"].count("\nRow ")+1, PAL=P, NAME=N, L="A1") + "\n" + REF + "\n" + PIXEL + LOCKS + f"\nCHARACTER (original ninja, pixel art, dark 1px outline, max 16 colors, {PROP}): {n['char']}\n\nROWS:\n{n['A1']}\n"
    out["STYLE"] = STYLE_RULES.format(PAL=P, NAME=N) + "\n" + REF + "\n" + PIXEL + f"\nCHARACTER (original ninja, pixel art, dark 1px outline, max 16 colors, {PROP}): {n['char']}\n\nPOSE: one standing idle pose: {n.get('STYLEPOSE', 'a relaxed idle stance that shows his personality')}.\n"
    if n.get("refchar"): out["A1"] = out["A1"].replace(REF, REFC.format(REFCHAR=n["refchar"], NAME=N.title(), LOOK=n["look"]))   # só um sprite de ref (o melhor do elenco)
    elif n.get("inroster"): out["A1"] = out["A1"].replace(REF, REFK.format(NAME=N.title(), LOOK=n["look"]))   # regera de ninja que já está no roster
    if n.get("styleref"): out["A1"] = out["A1"].replace("\nCHARACTER (original", STYLEREF.format(NAME=N.title(), LOOK=n["look"]) + "\nCHARACTER (original", 1)
    cr = lambda t: t.count("\nRow ")+1   # nº de linhas do lote, contado do texto
    out["A2"] = lot((cr(n["A2"]), n["A2"]), "A2", False); out["B1"] = lot((cr(n["B1"]), n["B1"]), "B1", False)
    out["B2"] = lot((cr(n["B2"]), n["B2"]), "B2", False)
    if "C" in n: out["C"] = lot((cr(n["C"]), n["C"]), "C", False)
    if "A1B" in n: out["A1B"] = lot((cr(n["A1B"]), n["A1B"]), "A1B", False)
    if "CH" in n: out["CH"] = lot((3, n["CH"]), "CH", False)
    if "CL" in n: out["CL"] = RULES.format(N=4, PAL=P, NAME=N, L="CL") + "\n" + n["CLINTRO"] + PIXEL + LOCKS + "\nROWS:\n" + n["CL"] + "\n"
    if "U" in n: out["U"] = lot((3, n["U"]), "U", False)
    out["D"] = PIXEL + "\n" + DBLOCK.format(PAL=P, NAME=N) + n["D"] + "\n"
    out.update(n.get("DR", {}))   # peças grandes do dragão (1 imagem por peça, texto pronto)
    return {a: _craft(_dist(n, _colors(n, t))) for a, t in out.items()}
def one_row(k, lote, idx):
    """Prompt de UMA linha de um lote (regra do dono 25/11/2026: gerar linha a linha, a anterior serve de ref da próxima)."""
    swap = None
    G = os.environ.get("GRID")                      # ex.: GRID=2x5 (10 poses) ou GRID=4x5 (20 poses): uma animação longa em várias linhas
    if G and lote == "A1":
        gr, gc = (int(v) for v in G.lower().split("x")); key = f"{os.environ.get('ANIM', 'A1')}_{gr * gc}"
        if key in NINJAS[k]: swap = NINJAS[k]["A1"]; NINJAS[k]["A1"] = NINJAS[k][key]
    try: t = build(k)[lote]
    finally:
        if swap is not None: NINJAS[k]["A1"] = swap
    rows = [l for l in t.split("\n") if l.startswith("Row ")]
    r = rows[idx - 1]
    head, tail = t.split("\nROWS:\n")
    import re
    n_old = len(rows)
    if os.environ.get("COLS"): head = head.replace("× 8 columns", f"× {os.environ['COLS']} columns").replace("EXACTLY 8 columns", f"EXACTLY {os.environ['COLS']} columns")   # ex.: COLS=5 pras 5 poses-chave do Bitmapflow
    head = head.replace(f"exactly {n_old} rows", "exactly 1 row").replace(f"EXACTLY {n_old} rows", "EXACTLY 1 row").replace(f"The image has {n_old} rows, not more.", "The image has 1 row, not more.")
    head = head.replace(f'LOTE {lote}"', f'LOTE {lote} L{idx}"')
    if G:
        N_ = gr * gc; shape = ("(each cell about as tall as wide, so the whole canvas is square)" if gr == gc else f"(each cell about as tall as wide, so the canvas is about {gc}:{gr})") if gr > 1 else "(landscape canvas)"
        head = "\n".join((f"1. GRID: exactly {gr} {'row' if gr == 1 else 'rows'} × {gc} columns, equal-sized cells {shape}." if l.startswith("1. GRID") else
                          (f"2. The {N_} cells form ONE single animation read in order: each row left to right, from the top row to the bottom row." if gr > 1 else f"2. The {N_} cells form ONE single animation read left to right.") if l.startswith("2. Each row") else
                          f"3. Every one of the {N_} cells is filled with exactly one pose." if l.startswith("3. Render only") else l) for l in head.split("\n"))
    return _craft(head + "\nROWS:\n" + re.sub(r"^Row \d+:", "Row 1:", r) + "\n")
TRIP_ROW = ("Row 1: TRIP (the victim of a low sweep kick), 6 frames, ONLY the character, no effects: "
 "Frame 1 HIT: the legs are swept out from under the character, the body still almost upright, surprised. "
 "Frame 2 LIFTED: both feet off the ground, the body tilting toward horizontal, held items swinging out. "
 "Frame 3 SPIN: the body nearly horizontal, low to the ground, mid-rotation, hair and cloth trailing. "
 "Frame 4 SPIN END: the body horizontal, back toward the ground, about to land. "
 "Frame 5 IMPACT: the character lands flat on the back, body horizontal and parallel to the ground (never vertical). "
 "Frame 6 LIES STILL: flat on the ground, slightly relaxed, every held item complete right beside the body (cells 7 to 8 EMPTY). "
 "NO dust, NO impact marks, NO ground line, NO shadow: the dust is a separate sheet drawn later.")
POEIRA = """STRICT RULES - EFFECT SHEET, NO CHARACTER:
1. GRID: exactly 2 rows × 6 columns, equal-sized cells, landscape canvas.
2. NO character, NO person, NO body, NO ground line, NO shadow. Only dust.
3. Each row is one independent effect; every cell is one moment of it, all 6 cells filled.
4. Dust drawn as hard-edged opaque pixel clusters in flat colors (max 8 colors): sand beige, warm gray, pale tan, dark brown outline 1px. No gradients, no soft fades, no transparency, no glow.
5. Each effect stays fully inside its cell with a 10% safe margin. Effect travels LEFT to RIGHT. Dust is centered at the bottom of the cell (where it touches the ground).
6. BACKGROUND: uniform flat pure green #00FF00. No green on the dust. No labels, text, borders or grid lines.
ROWS:
Row 1: LANDING DUST, 6 frames: a character falls flat on the ground; a wide low puff of dust bursts sideways, grows, then thins and breaks into a few separate small clumps.
Row 2: SLIDE DUST, 6 frames: a low trail of dust kicked up behind a body sliding to the right along the ground; small clumps lift, drift back and fall.
"""
def trip_prompt(k):
    n = NINJAS[k]; P = n["pal"]; N = n["name"]
    t = RULES.format(N=1, PAL=P, NAME=N, L="TRIP").replace("exactly 1 rows", "exactly 1 row") + "\n" + TRUTH.format(NAME=N.title(), LOOK=n["look"]) + PIXEL + LOCKS + "\nROWS:\n" + TRIP_ROW + "\n"
    return _colors(n, t) + REGEN["mao"] + "\n" + REGEN["fx"] + "\n"

